const {
  Document, Packer, Paragraph, TextRun, AlignmentType, ImageRun,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle,
  convertMillimetersToTwip
} = require("docx");
const fs = require("fs");
const path = require("path");

// ── Burapha Science Journal house style ──────────────────────────────────
const F = "Cordia New";
const S18 = 36, S14 = 28, S12 = 24;
const IND = { firstLine: convertMillimetersToTwip(12.5) };
const SPC = { after: 0 };
const PAGE_W_MM = 160;   // 210 − 25 − 25

const t = (text, o = {}) => new TextRun({
  text, font: F, size: o.size || S14, bold: !!o.b, italics: !!o.i,
  underline: o.u ? {} : undefined, superScript: !!o.sup, subScript: !!o.sub
});

// inline markup:  *bold*  /italic/  ~underline~  ^sup^  _sub_
function runs(str, size = S14) {
  const out = [];
  const re = /(\*[^*]+\*|\/[^/]+\/|~[^~]+~|\^[^^]+\^|_[^_]+_)/g;
  let last = 0, m;
  while ((m = re.exec(str)) !== null) {
    if (m.index > last) out.push(t(str.slice(last, m.index), { size }));
    const inner = m[0].slice(1, -1), k = m[0][0];
    out.push(t(inner, {
      size, b: k === "*", i: k === "/", u: k === "~",
      sup: k === "^", sub: k === "_"
    }));
    last = re.lastIndex;
  }
  if (last < str.length) out.push(t(str.slice(last), { size }));
  return out;
}

const P = s => new Paragraph({ children: runs(s), alignment: AlignmentType.JUSTIFIED, indent: IND, spacing: SPC });
const PL = s => new Paragraph({ children: runs(s), alignment: AlignmentType.JUSTIFIED, spacing: SPC });
const BLANK = () => new Paragraph({ children: [t("")], spacing: SPC });
const CTR = (s, size, o = {}) => new Paragraph({
  children: runs(s, size || S14).map(r => r),
  alignment: AlignmentType.CENTER, spacing: o.spacing || SPC
});
const SEC = s => new Paragraph({ children: [t(s, { b: true })], spacing: { before: 240, after: 0 } });
const SUB = s => new Paragraph({ children: [t(s, { u: true })], spacing: { before: 160, after: 0 } });
const EQ = s => new Paragraph({ children: runs(s), alignment: AlignmentType.CENTER, spacing: { before: 120, after: 120 } });
const CAP = (lab, txt, center) => new Paragraph({
  children: [t(lab + "  ", { i: true }), t(txt)],
  alignment: center ? AlignmentType.CENTER : AlignmentType.LEFT,
  spacing: { before: 120, after: 60 }
});
const NOTE = s => new Paragraph({ children: runs(s, S12), spacing: { before: 40, after: 0 } });

function figure(file, widthMm) {
  const buf = fs.readFileSync(path.join("fig", file));
  const dims = pngSize(buf);
  const w = (widthMm || PAGE_W_MM);
  const h = w * dims.h / dims.w;
  return new Paragraph({
    children: [new ImageRun({
      type: "png", data: buf,
      transformation: { width: mmToPx(w), height: mmToPx(h) }
    })],
    alignment: AlignmentType.CENTER, spacing: { before: 180, after: 0 }
  });
}
const mmToPx = mm => Math.round(mm * 96 / 25.4);
function pngSize(buf) {
  return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
}

function table(headers, rows, widths, aligns) {
  const total = widths.reduce((a, b) => a + b, 0);
  const cell = (txt, w, i, head) => new TableCell({
    width: { size: w, type: WidthType.DXA },
    shading: head ? { type: ShadingType.CLEAR, fill: "F2F2F2" } : undefined,
    margins: { top: 30, bottom: 30, left: 70, right: 70 },
    children: [new Paragraph({
      children: runs(String(txt), S12),
      alignment: (aligns && aligns[i] === "l") ? AlignmentType.LEFT : AlignmentType.CENTER,
      spacing: { after: 0 }
    })]
  });
  return new Table({
    columnWidths: widths, width: { size: total, type: WidthType.DXA },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 8 },
      bottom: { style: BorderStyle.SINGLE, size: 8 },
      left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE },
      insideVertical: { style: BorderStyle.NONE },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2, color: "C0C0C0" }
    },
    rows: [
      new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, widths[i], i, true)) }),
      ...rows.map(r => new TableRow({ children: r.map((c, i) => cell(c, widths[i], i, false)) }))
    ]
  });
}

const B = [];
const add = x => Array.isArray(x) ? B.push(...x) : B.push(x);

