add(SEC("Introduction"));

add(P("ปริมาณฝนเป็นตัวแปรภูมิอากาศที่มีความสำคัญต่อการประเมินทรัพยากรน้ำ การจัดการความเสี่ยงจากอุทกภัยและภัยแล้ง และการวางแผนปรับตัวต่อการเปลี่ยนแปลงสภาพภูมิอากาศ ในเอเชียตะวันออกเฉียงใต้ แนวโน้มของปริมาณฝนเฉลี่ยแตกต่างกันตามพื้นที่ ชุดข้อมูล และฤดูกาล ขณะที่หลักฐานเกี่ยวกับการเพิ่มขึ้นของความถี่และความรุนแรงของฝนหนักมีความชัดเจนกว่า (IPCC, 2021) Ge et al. (2021) วิเคราะห์ดัชนีฝนสุดขั้วในภูมิภาคนี้จากแบบจำลอง CMIP6 จำนวน 15 แบบจำลอง และพบว่าค่ามัธยฐานของกลุ่มแบบจำลองอธิบายลักษณะของฝนสุดขั้วได้ดีกว่าแบบจำลองเดี่ยว โดยการเพิ่มขึ้นของฝนสุดขั้วมีนัยสำคัญเหนือคาบสมุทรอินโดจีนและกลุ่มเกาะมาเลย์ การนำข้อมูลจากแบบจำลองภูมิอากาศไปใช้ในระดับพื้นที่จึงต้องอาศัยข้อมูลที่สะท้อนทั้งปริมาณ การกระจายตัว และลักษณะของเหตุการณ์ฝนได้อย่างเหมาะสม"));

add(P("แบบจำลองภูมิอากาศโลกภายใต้โครงการ Coupled Model Intercomparison Project Phase 6 (CMIP6) เป็นแหล่งข้อมูลหลักสำหรับการศึกษาดังกล่าว อย่างไรก็ตาม ผลลัพธ์จากแบบจำลองยังมีความคลาดเคลื่อนเชิงระบบเมื่อเปรียบเทียบกับข้อมูลตรวจวัด โดยเฉพาะปริมาณฝนซึ่งได้รับอิทธิพลจากกระบวนการพาความร้อน ภูมิประเทศ ระบบมรสุม และกระบวนการระดับท้องถิ่นที่แบบจำลองความละเอียดหยาบไม่สามารถแทนได้อย่างสมบูรณ์ (Maraun, 2016) ความแตกต่างระหว่างข้อมูลระดับกริดกับข้อมูลสถานีจึงปรากฏทั้งในค่าเฉลี่ย ความถี่ของวันฝนตก รูปร่างของการแจกแจง และค่าฝนสุดขั้ว ข้อจำกัดนี้มีความสำคัญต่อการประยุกต์ใช้ในงานอุทกวิทยา ซึ่งข้อมูลป้อนเข้าต้องมีลักษณะเชิงสถิติสอดคล้องกับสภาพภูมิอากาศระดับพื้นที่ (Teutschbein & Seibert, 2012)"));

add(P("การปรับแก้อคติจึงถูกใช้เป็นขั้นตอนมาตรฐานก่อนนำข้อมูลแบบจำลองไปใช้ โดยมีเป้าหมายเพื่อปรับคุณสมบัติเชิงสถิติของข้อมูลจำลองให้ใกล้เคียงกับข้อมูลตรวจวัด มิใช่การแก้ไขกระบวนการทางกายภาพที่อยู่เบื้องหลังการจำลอง (Ehret et al., 2012) ในบรรดาวิธีที่พัฒนาขึ้น วิธีเชิงควอนไทล์เป็นกลุ่มที่ได้รับความนิยมสูงสุดเนื่องจากปรับรูปร่างของการแจกแจงได้โดยไม่ต้องกำหนดรูปแบบฟังก์ชันล่วงหน้า แต่การจับคู่ควอนไทล์แบบดั้งเดิมอาจบิดเบือนสัญญาณการเปลี่ยนแปลงของแบบจำลองในอนาคตได้ (Cannon et al., 2015) วิธี Quantile Delta Mapping (QDM) พัฒนาขึ้นเพื่อตอบข้อจำกัดนี้ โดยปรับแก้อคติในแต่ละตำแหน่งของการแจกแจงพร้อมกับรักษาสัดส่วนการเปลี่ยนแปลงเชิงสัมพัทธ์ของแบบจำลองไว้ (Cannon et al., 2015) Tong et al. (2021) ประยุกต์ทั้งวิธีจับคู่ควอนไทล์และ QDM กับผลการจำลองรายวันเหนือประเทศจีนจากแบบจำลองภูมิอากาศระดับภูมิภาค และพบว่าทั้งสองวิธีลดความคลาดเคลื่อนเชิงระบบได้ แต่ QDM รักษาสัญญาณการเปลี่ยนแปลงไว้ได้ดีกว่า ทั้งนี้ QDM ยังคงเป็นวิธีเชิงสถิติที่อาศัยความสัมพันธ์ระหว่างข้อมูลจำลองกับข้อมูลตรวจวัดซึ่งประมาณขึ้นจากช่วงเวลาหนึ่ง แล้วนำไปใช้กับช่วงเวลาอื่นภายใต้ข้อสมมติโดยนัยว่าความสัมพันธ์ดังกล่าวเสถียรเพียงพอที่จะถ่ายทอดข้ามช่วงเวลาได้ ข้อสมมตินี้ยังได้รับการตรวจสอบไม่มากนัก (Maraun & Widmann, 2018)"));

add(P("ในระดับภูมิภาค มีงานที่ประเมินแบบจำลอง CMIP6 สำหรับปริมาณฝนอยู่พอสมควร Supharatid et al. (2022) ใช้แบบจำลอง CMIP6 จำนวน 18 แบบจำลองคาดการณ์การเปลี่ยนแปลงของอุณหภูมิและปริมาณฝนในเอเชียตะวันออกเฉียงใต้แผ่นดินใหญ่ ซึ่งครอบคลุมประเทศไทย ภายใต้สถานการณ์ SSP2-4.5 และ SSP5-8.5 สำหรับภาคใต้ของประเทศไทย Kuinkel et al. (2024) วิเคราะห์ดัชนีฝนสุดขั้วจากข้อมูลตรวจวัดร่วมกับแบบจำลอง CMIP6 จำนวน 6 แบบจำลอง และรายงานแนวโน้มปริมาณฝนที่เพิ่มขึ้นพร้อมกับความสัมพันธ์กับปรากฏการณ์เอนโซที่ลดลงภายใต้ภาวะโลกร้อน ในด้านการปรับแก้อคติโดยตรง Humphries et al. (2024) เปรียบเทียบวิธี delta change, quantile mapping และ empirical quantile mapping กับข้อมูลจากสถานีตรวจวัด 30 แห่งในภาคใต้ของประเทศไทย และสรุปว่าวิธี delta change ให้ผลดีที่สุดในบรรดาสามวิธี ขณะที่ Arif Rafhida et al. (2025) ประยุกต์ QDM กับข้อมูล CMIP6 ที่สถานีตรวจวัด 7 แห่งรอบทะเลสาบโทบา ประเทศอินโดนีเซีย โดยเปรียบเทียบการประมาณฟังก์ชันการแจกแจงแบบแยกรายเดือนกับแบบรวมทุกเดือน และพบว่าประสิทธิผลของทั้งสองแนวทางขึ้นกับลักษณะของสถานี"));

add(P("งานที่ทบทวนข้างต้นแสดงความก้าวหน้าในการเตรียมข้อมูลภูมิอากาศสำหรับภูมิภาคนี้ อย่างไรก็ตาม ช่องว่างที่ยังคงอยู่มิได้อยู่ที่วิธีการปรับแก้ หากอยู่ที่กรอบการประเมินผล กล่าวคือ ในบรรดางานที่ทบทวนข้างต้น ไม่มีงานใดที่แยกช่วงประมาณฟังก์ชันการแปลงออกจากช่วงประเมินผลตามลำดับเวลาอย่างสิ้นเชิง การประเมินด้วยช่วงเวลาเดียวกับที่ใช้ประมาณฟังก์ชันบ่งชี้ได้เพียงความสอดคล้องภายในชุดข้อมูลที่ใช้สร้างฟังก์ชัน แต่ไม่สามารถแสดงได้ว่าความสัมพันธ์ที่ประมาณขึ้นยังคงใช้ได้กับข้อมูลในช่วงเวลาที่ไม่เคยนำมาใช้ ค่าประสิทธิภาพที่ได้จึงมีแนวโน้มสูงเกินจริง (Maraun et al., 2017) ประเด็นนี้มีความสำคัญเป็นพิเศษสำหรับแบบจำลองที่ดำเนินการแบบอิสระ ซึ่งมิได้ถูกออกแบบให้สร้างลำดับเหตุการณ์รายวันให้ตรงกับที่เกิดขึ้นจริง ความเที่ยงตรงเชิงการแจกแจงกับความสอดคล้องเชิงเวลาจึงเป็นคุณสมบัติคนละมิติที่ควรแยกประเมินออกจากกัน"));

add(P("การศึกษานี้จึงมีวัตถุประสงค์เพื่อประเมินความสามารถในการถ่ายทอดข้ามช่วงเวลาของการปรับแก้อคติด้วยวิธี QDM สำหรับข้อมูลปริมาณฝนรายวันจากแบบจำลอง CMIP6 จำนวน 5 แบบจำลอง ที่สถานีตรวจวัด 12 แห่งในจังหวัดประจวบคีรีขันธ์ ซึ่งเป็นพื้นที่ที่มีอ่าวไทยทางด้านตะวันออกและแนวเทือกเขาตะนาวศรีทางด้านตะวันตก จึงมีความแปรปรวนของฝนเชิงพื้นที่สูงภายในจังหวัดเดียว ฟังก์ชันการแปลงถูกประมาณจากข้อมูลช่วงปี ค.ศ. 1981-2000 เท่านั้น จากนั้นตรึงค่าพารามิเตอร์และนำไปใช้กับข้อมูลช่วงปี ค.ศ. 2001-2014 ที่เป็นอิสระจากการปรับแก้โดยสมบูรณ์ การประเมินแยกตัวชี้วัดออกเป็นสี่กลุ่ม ได้แก่ ความคลาดเคลื่อนเชิงระบบ ความเที่ยงตรงเชิงการแจกแจง ดัชนีที่อาศัยขนาดความคลาดเคลื่อน และความสอดคล้องเชิงเวลา เพื่อระบุว่าการปรับแก้อคติถ่ายทอดคุณสมบัติประเภทใดได้ และคุณสมบัติใดยังคงถูกจำกัดโดยธรรมชาติของแบบจำลองต้นทาง นอกจากนี้ยังประเมินกลุ่มแบบจำลองเฉลี่ยแบบไม่ถ่วงน้ำหนักเป็นวัตถุประสงค์รอง เพื่อพิจารณาว่าการเฉลี่ยข้ามแบบจำลองให้ผลแตกต่างจากแบบจำลองเดี่ยวอย่างไรภายใต้กรอบการประเมินเดียวกัน"));

/* ═══════════════════════════ METHODOLOGY ═══════════════════════════ */
add(SEC("Methodology"));

add(SUB("2.1 พื้นที่ศึกษา"));
add(P("พื้นที่ศึกษาครอบคลุมจังหวัดประจวบคีรีขันธ์ ซึ่งตั้งอยู่บนชายฝั่งตะวันตกของอ่าวไทย มีลักษณะเป็นแนวแคบยาวในทิศเหนือ-ใต้ ขอบด้านตะวันออกติดอ่าวไทย และขอบด้านตะวันตกถูกกำหนดโดยแนวเทือกเขาตะนาวศรี พื้นที่ระหว่างสองแนวประกอบด้วยที่ราบชายฝั่งแคบและที่ราบภายใน ภูมิอากาศอยู่ภายใต้อิทธิพลของลมมรสุมตะวันตกเฉียงใต้และลมมรสุมตะวันออกเฉียงเหนือ ร่วมกับพายุหมุนเขตร้อนที่เคลื่อนผ่านเป็นครั้งคราว การศึกษานี้ใช้ข้อมูลจากสถานีตรวจวัดน้ำฝน 12 แห่ง ที่กระจายครอบคลุมพื้นที่ชายฝั่ง ที่ราบภายใน และเชิงเขา ดังแสดงในรูปที่ 1"));

add(SUB("2.2 ข้อมูลปริมาณฝนและแบบจำลอง CMIP6"));
add(P("ข้อมูลฝนสังเกตการณ์รายวันจากสถานีตรวจวัด 12 แห่ง ครอบคลุมช่วงปี ค.ศ. 1981-2014 รวม 12,418 วัน ผ่านการตรวจสอบคุณภาพก่อนการวิเคราะห์ ประกอบด้วยการแทนค่าที่ประกาศเป็นค่าสูญหายด้วยค่าว่าง การจัดการค่าติดลบที่เกิดจากการแปลงหน่วยโดยปรับเป็นศูนย์เฉพาะกรณีที่อยู่ภายในค่าความคลาดเคลื่อนที่กำหนด และการคัดกรองคุณภาพสถานีตามเกณฑ์ที่กำหนดไว้ล่วงหน้าสามกลุ่ม ได้แก่ ความเป็นไปได้เชิงกายภาพ โครงสร้างเชิงเวลา และความเป็นเนื้อเดียวของอนุกรม รายละเอียดของสถานีและผลการคัดกรองแสดงในตารางที่ 1"));
add(P("ข้อมูลตรวจวัดของทุกสถานีผ่านการควบคุมคุณภาพก่อนการวิเคราะห์ โดยใช้เกณฑ์สองข้อที่กำหนดไว้ล่วงหน้า ได้แก่ ความครบถ้วนของข้อมูลไม่น้อยกว่าร้อยละ 95 และความเป็นเนื้อเดียวของอนุกรมปริมาณฝนรายปีตามการทดสอบของ Pettitt (1979) ที่ระดับนัยสำคัญ 0.05 ผลการตรวจสอบพบว่าสถานีทั้ง 12 แห่งมีข้อมูลครบถ้วนร้อยละ 100 และผ่านการทดสอบความเป็นเนื้อเดียวทุกสถานี จึงคงไว้ในเครือข่ายการวิเคราะห์ทั้งหมดโดยไม่มีสถานีใดถูกคัดออก"));
add(P("นอกเหนือจากเกณฑ์ควบคุมคุณภาพข้างต้น การศึกษานี้รายงานลักษณะของบันทึกรายสถานีไว้ในตารางที่ 1 ด้วย ได้แก่ ความเข้มฝนเฉลี่ยต่อวันฝนตก ปริมาณฝนรายวันสูงสุด และค่าสหสัมพันธ์ในตัวเองที่ความหน่วง 1 วัน ค่าเหล่านี้แสดงให้เห็นว่าบันทึกของแต่ละสถานีมีลักษณะแตกต่างกันพอสมควร โดยความเข้มฝนเฉลี่ยต่อวันฝนตกอยู่ระหว่าง 5.1 ถึง 13.1 มิลลิเมตรต่อวัน และปริมาณฝนรายวันสูงสุดตลอด 34 ปี อยู่ระหว่าง 54.2 ถึง 298.5 มิลลิเมตรต่อวัน ค่าดังกล่าวรายงานไว้เพื่อความโปร่งใสเท่านั้น มิได้ใช้เป็นเกณฑ์คัดเลือกหรือจัดระดับสถานี เนื่องจากการจัดระดับคุณภาพเพิ่มอีกชั้นหนึ่งอยู่นอกขอบเขตของคำถามวิจัย ทั้งนี้ ความแตกต่างของลักษณะบันทึกดังกล่าวถูกนำไปพิจารณาเป็นข้อจำกัดในหัวข้อ 4.5"));
add(P("ข้อมูลแบบจำลองภูมิอากาศโลกใช้ผลการจำลองช่วงประวัติศาสตร์จากแบบจำลอง CMIP6 จำนวน 5 แบบจำลอง รายละเอียดแสดงในตารางที่ 2 การจับคู่ข้อมูลแบบจำลองกับตำแหน่งสถานีใช้วิธีเลือกจุดกริดที่ใกล้ที่สุด ทั้งนี้ เนื่องจากความละเอียดเชิงพื้นที่ของแบบจำลองอยู่ในระดับ 1 ถึง 3 องศา สถานีจำนวนมากจึงตกอยู่ในกริดเซลล์เดียวกัน เมื่อพิจารณาจำนวนค่าที่แตกต่างกันของปริมาณฝนรายวันข้ามสถานีทั้ง 12 แห่ง พบว่าแบบจำลอง ACCESS-ESM1-5, CanESM5 และ MIROC6 ให้ค่าที่แตกต่างกันเพียง 2 ค่าต่อวัน ส่วน CESM2 และ EC-Earth3 ให้ 3 ค่าต่อวัน แสดงว่าปริมาณสารสนเทศเชิงพื้นที่ที่ใช้ได้จริงในระดับสถานีมีจำกัด และสถานีทั้ง 12 แห่งไม่เป็นอิสระต่อกันในความหมายทางสถิติ เนื่องจากการดึงข้อมูลด้วยจุดกริดที่ใกล้ที่สุดทำให้สถานีจำนวนหนึ่งได้รับค่าจากกริดเซลล์เดียวกัน คู่การประเมิน 60 คู่ที่รายงานตลอดบทความจึงหมายถึงจำนวนชุดการประเมิน มิใช่หน่วยเชิงพื้นที่ที่เป็นอิสระต่อกัน 60 หน่วย"));
add(P("ปฏิทินของแบบจำลองแตกต่างกัน โดย CESM2 และ CanESM5 ใช้ปฏิทินแบบ 365 วัน จึงมีข้อมูลรวม 12,410 วัน ขณะที่แบบจำลองอื่นและข้อมูลสังเกตการณ์มี 12,418 วัน การจับคู่ข้อมูลดำเนินการบนวันที่ที่ปรากฏร่วมกันระหว่างข้อมูลสังเกตการณ์กับแบบจำลองแต่ละตัว โดยไม่บังคับให้ทุกแบบจำลองเหลือจำนวนวันเท่ากัน"));

