add(SUB("2.4 การปรับแก้อคติด้วยวิธีควอนไทล์เดลตาแมปปิง"));
add(P("กำหนดให้ P^obs^_cal_ และ P^mod^_cal_ คือข้อมูลฝนสังเกตการณ์และข้อมูลแบบจำลองในช่วงปรับแก้ ตามลำดับ ความสัมพันธ์ของการปรับแก้ถูกประมาณจากข้อมูลทั้งสองชุดนี้เท่านั้น แล้วนำไปใช้กับข้อมูลแบบจำลองในช่วงตรวจสอบ P^mod^_val_ เพื่อให้ได้ข้อมูลที่ปรับแก้แล้ว P^QDM^_val_ ซึ่งนำไปเปรียบเทียบกับ P^obs^_val_ ค่าปรับแก้คำนวณตามสมการที่ (1)"));
add(EQ("x̂ = F^−1^_o,h_(τ) × [ x / F^−1^_m,h_(τ) ]          (1)"));
add(P("โดยที่ τ = F_m,p_(x) คือตำแหน่งควอนไทล์ของค่าฝนจากแบบจำลองภายในการแจกแจงของแบบจำลองในช่วงเป้าหมาย F^−1^_o,h_ คือฟังก์ชันการแจกแจงสะสมผกผันของข้อมูลสังเกตการณ์ในช่วงปรับแก้ และ F^−1^_m,h_ คือฟังก์ชันการแจกแจงสะสมผกผันของแบบจำลองในช่วงปรับแก้ พจน์ในวงเล็บเหลี่ยมคืออัตราส่วนการเปลี่ยนแปลงเชิงสัมพัทธ์ที่ใช้รักษาสัญญาณของแบบจำลองไว้ (Cannon et al., 2015) การประมาณค่าฟังก์ชันการแจกแจงใช้การแจกแจงเชิงประจักษ์และการประมาณค่านอกช่วงแบบค่าคงที่ที่ปลายหางทั้งสองด้าน"));
add(P("การปรับความถี่วันฝนตกดำเนินการโดยกำหนดค่าเกณฑ์ฝั่งแบบจำลองให้ความถี่วันฝนตกในช่วงปรับแก้ตรงกับข้อมูลสังเกตการณ์ แล้วตรึงค่าเกณฑ์ดังกล่าวไว้เพื่อใช้กับช่วงตรวจสอบโดยไม่ประมาณใหม่ ผลที่ตามมาคือ ความสอดคล้องของความถี่วันฝนตกในช่วงปรับแก้เป็นคุณสมบัติที่เกิดจากการออกแบบวิธีการ มิใช่ผลการตรวจสอบความสามารถ การศึกษานี้จึงแยกรายงานตัวชี้วัดกลุ่มนี้ออกจากตัวชี้วัดที่ใช้ตรวจสอบความสามารถอย่างชัดเจน"));
add(P("อนึ่ง เมื่อช่วงเป้าหมายเป็นช่วงเดียวกับช่วงปรับแก้ อัตราส่วนการเปลี่ยนแปลงเชิงสัมพัทธ์ในสมการที่ (1) มีค่าเท่ากับหนึ่งตามนิยาม ทำให้วิธี QDM ลดรูปเป็นวิธีจับคู่ควอนไทล์เชิงประจักษ์พอดี ผลการคำนวณยืนยันเอกลักษณ์ดังกล่าว โดยค่าความแตกต่างสูงสุดระหว่างสองวิธีในช่วงปรับแก้เท่ากับศูนย์ในทุกแบบจำลอง ซึ่งเป็นการตรวจสอบความถูกต้องภายในของการดำเนินการ"));

add(SUB("2.5 การประเมินประสิทธิภาพ"));
add(P("การประเมินประสิทธิภาพดำเนินการเฉพาะช่วงปี ค.ศ. 2001-2014 โดยเปรียบเทียบข้อมูลแบบจำลองก่อนการปรับแก้และข้อมูลที่ปรับแก้แล้วกับข้อมูลสังเกตการณ์ในช่วงเดียวกัน ตัวชี้วัดที่ใช้แบ่งตามบทบาทได้ดังนี้ ขนาดของความคลาดเคลื่อนพิจารณาจาก RMSE และ MAE ความคลาดเคลื่อนเชิงระบบพิจารณาจาก MBE และ PBIAS ความสอดคล้องเชิงเวลาพิจารณาจากสัมประสิทธิ์สหสัมพันธ์เพียร์สัน และประสิทธิภาพเชิงอุทกวิทยาโดยรวมพิจารณาจาก NSE และ KGE นอกจากนี้ ได้เพิ่มตัวชี้วัดเชิงการแจกแจง ได้แก่ ค่าสถิติ Kolmogorov-Smirnov ค่า Perkins skill score (Perkins et al., 2007) ความลำเอียงสัมพัทธ์ของควอนไทล์ที่ 95 และ 99 และดัชนี Rx1day เพื่อประเมินคุณสมบัติที่ดัชนีความคลาดเคลื่อนไม่ครอบคลุม"));
add(P("หน่วยของการเปรียบเทียบคือคู่การประเมิน รวม 60 คู่ การทดสอบนัยสำคัญใช้การสุ่มซ้ำแบบบล็อกโดยกำหนดให้ปีปฏิทินเป็นหน่วยบล็อก ซึ่งช่วงตรวจสอบมี 14 บล็อก ทำการสุ่มซ้ำ 2,000 ครั้ง เปรียบเทียบแบบจับคู่ภายในคู่การประเมินเดียวกัน แล้วควบคุมอัตราการค้นพบเท็จตามวิธีของ Benjamini and Hochberg (1995) บนกลุ่มสมมติฐานทั้งหมด 180 สมมติฐาน เหตุผลที่ไม่ใช้การทดสอบข้ามสถานีคือ สถานีทั้ง 12 แห่งไม่เป็นอิสระต่อกันดังที่ระบุไว้ข้างต้น การสรุปผลข้ามสถานีจึงรายงานในเชิงพรรณนาเป็นสัดส่วนของคู่ที่ปรับปรุงขึ้น"));

add(SUB("2.6 การประเมินแบบจำลองรายตัวและกลุ่มแบบจำลองเฉลี่ย"));
add(P("การประเมินดำเนินการรายแบบจำลองก่อน จากนั้นจึงสร้างกลุ่มแบบจำลองเฉลี่ยแบบไม่ถ่วงน้ำหนักตามสมการที่ (2)"));
add(EQ("MME_t_ = (1/M) Σ P_m,t_ ,  m = 1, …, M          (2)"));
