add(SUB("3.1 ลักษณะข้อมูลปริมาณฝนในช่วงปรับแก้และช่วงตรวจสอบ"));
add(P("ลักษณะของข้อมูลฝนสังเกตการณ์ในทั้งสองช่วงเวลาแสดงในรูปที่ 3 วัฏจักรฤดูกาลของทั้งสองช่วงมีรูปแบบสอดคล้องกัน โดยมีฝนสูงสุดในช่วงเดือนพฤษภาคมและเดือนกันยายนถึงตุลาคม ปริมาณฝนเฉลี่ยรายปีระดับภูมิภาคของสองช่วงใกล้เคียงกัน ขณะที่ความถี่วันฝนตกเฉลี่ยลดลงเล็กน้อยจาก 0.376 ในช่วงปรับแก้ เป็น 0.366 ในช่วงตรวจสอบ ช่วงตรวจสอบจึงมิได้แตกต่างจากช่วงปรับแก้ในลักษณะที่จะทำให้การประเมินเสียความหมาย"));
add(P("เมื่อพิจารณารายสถานีตามตารางที่ 1 บันทึกของแต่ละสถานีมีลักษณะแตกต่างกันพอสมควร ความเข้มฝนเฉลี่ยต่อวันฝนตกอยู่ระหว่าง 5.1 ถึง 13.1 มิลลิเมตรต่อวัน ปริมาณฝนรายวันสูงสุดตลอด 34 ปี อยู่ระหว่าง 54.2 ถึง 298.5 มิลลิเมตรต่อวัน และค่าสหสัมพันธ์ในตัวเองที่ความหน่วง 1 วัน อยู่ระหว่าง 0.19 ถึง 0.66 โดยสถานีที่มีความเข้มฝนต่ำจะมีความถี่วันฝนตกสูงและมีค่าสหสัมพันธ์ในตัวเองสูงไปด้วย ความแตกต่างนี้เป็นลักษณะของเครือข่ายตรวจวัดที่ใช้ และถูกนำไปพิจารณาในหัวข้อ 4.5"));
