add(SUB("3.4 ความสอดคล้องเชิงเวลาในสามมาตราส่วน"));
add(P("ตารางที่ 3 แสดงว่าความสอดคล้องเชิงเวลาไม่ได้รับการฟื้นคืนอย่างมีสาระในทั้งสามมาตราส่วนที่พิจารณา สัมประสิทธิ์สหสัมพันธ์ของค่าเบี่ยงรายเดือนภายหลังขจัดวัฏจักรฤดูกาลออกแล้วมีค่าเท่ากับ 0.011 ทั้งก่อนและหลังการปรับแก้ สัมประสิทธิ์สหสัมพันธ์ของปริมาณฝนรายปีเพิ่มขึ้นจาก 0.025 เป็น 0.038 ซึ่งยังคงใกล้ศูนย์ และสัมประสิทธิ์สหสัมพันธ์ของวัฏจักรฤดูกาลลดลงเล็กน้อยจาก 0.643 เป็น 0.629 โดยปรับปรุงขึ้นเพียงร้อยละ 47 ของคู่ ส่วนสัมประสิทธิ์สหสัมพันธ์รายเดือนลดลงจาก 0.342 เป็น 0.328"));
add(P("ผลชุดนี้แยกออกจากผลในหัวข้อ 3.3 อย่างชัดเจน กล่าวคือ ดัชนี RMSE, NSE และ KGE มิได้วัดความสอดคล้องเชิงเวลาโดยตรง เนื่องจากอนุกรมที่ตรงกันในเชิงจังหวะเวลาอาจได้คะแนนต่ำเพราะความแปรปรวนต่างกัน และในทางกลับกันก็เป็นจริงเช่นกัน การรายงานจึงแยกดัชนีสองกลุ่มนี้ออกจากกันตลอดบทความ"));

add(SUB("3.5 การแยกส่วนค่าความคลาดเคลื่อนกำลังสองเฉลี่ย"));
add(P("ผลที่ปรากฏในหัวข้อ 3.2 ถึง 3.4 สามารถเชื่อมโยงเข้าด้วยกันได้ผ่านการแยกส่วนค่าความคลาดเคลื่อนกำลังสองเฉลี่ยตามแนวทางของ Murphy (1988) ดังสมการที่ (3)"));
add(EQ("MSE = b^2^ + (σ_s_ − rσ_o_)^2^ + σ_o_^2^(1 − r^2^)          (3)"));
add(P("โดยที่ b คือความลำเอียงของค่าเฉลี่ย σ_s_ และ σ_o_ คือส่วนเบี่ยงเบนมาตรฐานของข้อมูลจำลองและข้อมูลสังเกตการณ์ตามลำดับ และ r คือสัมประสิทธิ์สหสัมพันธ์ จากสมการดังกล่าว ค่า MSE จะต่ำที่สุดเมื่ออัตราส่วน σ_s_/σ_o_ เท่ากับ r มิใช่เท่ากับหนึ่ง"));
add(P("ผลการวิเคราะห์ตามรูปที่ 7 (a) พบว่าสัมประสิทธิ์สหสัมพันธ์รายเดือนมีค่าเฉลี่ยเพียง 0.342 ขณะที่อัตราส่วนการกระจายของแบบจำลองดิบมีค่าเฉลี่ย 1.169 ซึ่งสูงกว่าค่าที่ทำให้ค่าความคลาดเคลื่อนต่ำสุดในทุกคู่ทั้ง 60 คู่ ภายหลังการปรับแก้ อัตราส่วนดังกล่าวเพิ่มขึ้นเป็น 1.286 และยังคงสูงกว่าค่าที่เหมาะสมในทุกคู่ รูปที่ 7 (b) แสดงว่าการเปลี่ยนแปลงของอัตราส่วนการกระจายกับการเปลี่ยนแปลงของค่า RMSE มีความสัมพันธ์กันอย่างเข้มข้น โดยมีค่าสัมประสิทธิ์สหสัมพันธ์อันดับของสเปียร์แมนเท่ากับ 0.95 (p < 0.001)"));
add(P("สมการที่ (3) ให้การแยกส่วนที่ถูกต้องแม่นยำสำหรับคู่การประเมินแต่ละคู่ เมื่อสรุปข้ามคู่ทั้ง 60 คู่ด้วยค่าเฉลี่ย ซึ่งเป็นค่าสรุปที่บวกกันได้ตามคุณสมบัติของการแยกส่วน พบว่าพจน์การกระจายเพิ่มขึ้น +2,891 ตารางมิลลิเมตรต่อเดือนกำลังสอง พจน์ความลำเอียงลดลง -237 และพจน์เฟสเพิ่มขึ้น +77 รวมเป็นการเปลี่ยนแปลงสุทธิ +2,731 ดังแสดงในรูปที่ 7 (c) นอกจากนี้ เมื่อพิจารณาเป็นรายคู่โดยไม่พึ่งค่าสรุปใด ๆ พบว่าพจน์การกระจายมีขนาดใหญ่ที่สุดในบรรดาสามพจน์ใน 56 จาก 60 คู่"));
add(P("ควรระบุด้วยว่า หากสรุปข้ามคู่ด้วยค่ามัธยฐานแทน ค่ามัธยฐานของแต่ละพจน์จะไม่บวกกันเท่ากับค่ามัธยฐานของผลรวม เนื่องจากมัธยฐานไม่มีสมบัติการบวก การศึกษานี้จึงเลือกรายงานด้วยค่าเฉลี่ยเพื่อรักษาความสอดคล้องของการแยกส่วน และรายงานสัดส่วนรายคู่ควบคู่กันเพื่อให้ข้อสรุปไม่ขึ้นกับการเลือกค่าสรุป"));
add(figure("Figure7_mechanism.png"));
add(CAP("Figure 7", "Factors associated with the change in error metrics after QDM correction: (a) dispersion ratio against the monthly correlation, with the dashed line marking the RMSE-optimal ratio; (b) change in dispersion ratio against change in RMSE; and (c) decomposition of the change in mean square error. Bars in (c) are means across the 60 evaluation combinations, which are additive, so the three components sum exactly to the total; whiskers show the interquartile range of the pairwise values and therefore describe the spread across combinations, not the uncertainty of the mean", true));

add(SUB("3.6 ความคงทนของข้อสรุป"));
add(P("การเปลี่ยนแปลงของประสิทธิภาพหลังการปรับแก้แตกต่างกันอย่างเป็นระบบทั้งระหว่างแบบจำลองและระหว่างสถานี ดังแสดงในรูปที่ 5 ในด้านค่า RMSE แบบจำลอง ACCESS-ESM1-5 มีค่าเพิ่มขึ้นมากที่สุดจาก 129.6 เป็น 147.9 มิลลิเมตรต่อเดือน ขณะที่ CanESM5 เป็นแบบจำลองเดียวที่มีค่าลดลงจาก 107.5 เป็น 106.4 มิลลิเมตรต่อเดือน ในด้านความลำเอียงของควอนไทล์ที่ 99 ผลกลับเป็นไปในทิศทางตรงข้าม โดยปรับปรุงขึ้นในเกือบทุกคู่ และปรับปรุงมากที่สุดที่สถานีซึ่งความคลาดเคลื่อนเชิงการแจกแจงของแบบจำลองดิบมีขนาดใหญ่ที่สุด ได้แก่ สถานี 500008 และ 500009"));
add(P("การวิเคราะห์ความไวสองแบบให้ผลตรงกันว่าข้อสรุปหลักไม่เปลี่ยนทิศทาง แบบแรกคือการเปลี่ยนวิธีจัดกลุ่มในการปรับแก้ และแบบที่สองคือการจำกัดหางบนของการแจกแจง การประมาณและตรึงฟังก์ชันการแปลงแยกตามเดือนปฏิทินให้ผลดีกว่าการรวมทุกเดือนในดัชนีเชิงเวลา โดยค่า RMSE รายเดือนลดลงจาก 124.7 เหลือ 109.3 มิลลิเมตรต่อเดือน สัดส่วนคู่ที่ปรับปรุงขึ้นเพิ่มจากร้อยละ 37 เป็นร้อยละ 63 และสัมประสิทธิ์สหสัมพันธ์ของวัฏจักรฤดูกาลเพิ่มจาก 0.629 เป็น 0.884 โดยไม่ทำให้ความลำเอียงของเหตุการณ์สุดขั้วแย่ลง ส่วนการจำกัดหางบนของการแจกแจงที่ 1.5 เท่าของค่าสูงสุดในช่วงปรับแก้ไม่มีผลอย่างมีสาระ โดยค่า PBIAS เปลี่ยนแปลง -0.08 จุดร้อยละ และความลำเอียงของดัชนี Rx1day เปลี่ยนแปลง -0.79 จุดร้อยละ กล่าวโดยสรุป ขนาดของผลแปรผันตามทางเลือกเชิงวิเคราะห์ แต่ข้อสรุปหลักไม่เปลี่ยนแปลง"));
add(P("สำหรับกลุ่มแบบจำลองเฉลี่ยแบบไม่ถ่วงน้ำหนัก ซึ่งเป็นผลรอง ตารางที่ 4 และรูปที่ 6 แสดงว่ากลุ่มแบบจำลองเฉลี่ยของข้อมูลดิบมีค่า RMSE เท่ากับ 91.7 มิลลิเมตรต่อเดือน ต่ำกว่าแบบจำลองเดี่ยวทุกตัวที่มีค่าระหว่าง 92.3 ถึง 129.6 มิลลิเมตรต่อเดือน ภายหลังการปรับแก้ ค่าดังกล่าวเพิ่มขึ้นเป็น 93.8 มิลลิเมตรต่อเดือน แต่ยังคงต่ำกว่าแบบจำลองเดี่ยวทุกตัว อย่างไรก็ตาม ค่า NSE ยังคงติดลบทั้งก่อนและหลังการปรับแก้ ที่ -0.038 และ -0.085 ตามลำดับ และสัมประสิทธิ์สหสัมพันธ์รายเดือนลดลงเล็กน้อยจาก 0.440 เป็น 0.436 ข้อได้เปรียบของกลุ่มแบบจำลองเฉลี่ยจึงปรากฏเฉพาะในมิติของขนาดความคลาดเคลื่อน มิใช่ในมิติของความสอดคล้องเชิงเวลา"));
