/* ═════════════════════════════ DISCUSSION ═════════════════════════════ */
add(SEC("Discussion"));

add(SUB("4.1 การตรวจสอบข้ามช่วงเวลาแบบอิสระเผยให้เห็นการแลกเปลี่ยนเชิงสมรรถนะ"));
add(P("ข้อค้นพบหลักของการศึกษานี้มิใช่ว่าการปรับแก้อคติดีหรือไม่ดี แต่คือการที่กรอบการตรวจสอบข้ามช่วงเวลาแบบอิสระเปิดเผยการแลกเปลี่ยนที่กรอบการประเมินภายในช่วงปรับแก้เดียวกันมองไม่เห็น ฟังก์ชันการแปลงที่ประมาณจากช่วงปี ค.ศ. 1981-2000 ปรับปรุงคุณสมบัติเชิงการแจกแจงและลดความคลาดเคลื่อนเชิงระบบได้เมื่อนำไปใช้กับช่วงปี ค.ศ. 2001-2014 โดยไม่ปรับค่าใหม่ แต่ในขณะเดียวกันกลับทำให้ดัชนีที่อาศัยขนาดความคลาดเคลื่อนด้อยลงอย่างมีนัยสำคัญในคู่การประเมินส่วนใหญ่"));
add(P("ผลดังกล่าวบ่งชี้ว่าความสัมพันธ์ของการปรับแก้มีความสามารถในการถ่ายทอดข้ามช่วงเวลาในระดับหนึ่งภายในบันทึกประวัติศาสตร์ สำหรับคุณสมบัติบางประการเท่านั้น การตรวจสอบใช้การแบ่งช่วงเวลาเพียงรูปแบบเดียว โดยมีช่วงปรับแก้ 20 ปี และช่วงตรวจสอบ 14 ปี ข้อสรุปจึงเหมาะสมกับการอธิบายว่าเป็นการถ่ายทอดในระดับหนึ่ง มิใช่การถ่ายทอดอย่างสมบูรณ์ (Maraun et al., 2017) ข้อสังเกตนี้มีนัยต่อการตีความงานก่อนหน้าในภูมิภาคด้วย เนื่องจาก Humphries et al. (2024) รายงานว่าวิธี delta change ให้ผลดีกว่า quantile mapping ในภาคใต้ของประเทศไทย โดยประเมินภายในช่วงเวลาเดียวกับที่ใช้ปรับแก้ การจัดอันดับวิธีการที่ได้จากกรอบดังกล่าวจึงยังไม่ได้รับการทดสอบในเชิงการถ่ายทอดข้ามช่วงเวลา"));

add(SUB("4.2 เหตุใดการปรับปรุงเชิงการแจกแจงจึงเกิดร่วมกับการด้อยลงของดัชนีความคลาดเคลื่อน"));
add(P("โครงสร้างของค่าความคลาดเคลื่อนกำลังสองเฉลี่ยตามสมการที่ (3) ให้คำอธิบายที่ตรวจสอบได้จากข้อมูล Murphy (1988) แสดงว่าค่า MSE จะต่ำที่สุดเมื่ออัตราส่วนการกระจายเท่ากับสัมประสิทธิ์สหสัมพันธ์ มิใช่เท่ากับหนึ่ง ในพื้นที่ศึกษา สัมประสิทธิ์สหสัมพันธ์รายเดือนมีค่าเฉลี่ยเพียง 0.342 ขณะที่แบบจำลองดิบมีอัตราส่วนการกระจาย 1.169 ซึ่งสูงกว่าจุดที่เหมาะสมอยู่แล้วในทุกคู่ การปรับแก้อคติซึ่งคืนความเข้มฝนให้สอดคล้องกับการตรวจวัดจึงเพิ่มอัตราส่วนดังกล่าวเป็น 1.286 และเคลื่อนข้อมูลออกห่างจากจุดที่ทำให้ค่าความคลาดเคลื่อนต่ำสุด"));
add(P("การแยกส่วนรายคู่สนับสนุนคำอธิบายนี้ โดยพจน์การกระจายมีขนาดใหญ่ที่สุดในบรรดาสามพจน์ใน 56 จาก 60 คู่ และค่าเฉลี่ยข้ามคู่ของพจน์การกระจายเท่ากับ +2,891 ตารางมิลลิเมตรต่อเดือนกำลังสอง เทียบกับพจน์ความลำเอียงที่ -237 ผลชุดนี้จึงเป็นปัจจัยที่สัมพันธ์กับการเปลี่ยนแปลงของดัชนีความคลาดเคลื่อนที่สังเกตได้ในการประเมินครั้งนี้ มิใช่การพิสูจน์เชิงสาเหตุ และมิใช่คุณสมบัติทั่วไปของวิธีการปรับแก้อคติ"));
add(P("ขอบเขตของข้อสรุปนี้ต้องระบุให้ชัดเจนว่า มิได้หมายความว่าการคืนความแปรปรวนจะเพิ่มค่า RMSE เสมอไปในทุกกรณี เนื่องจากหากข้อมูลเดิมมีการกระจายต่ำกว่าค่า rσ_o_ การเพิ่มความแปรปรวนย่อมทำให้ค่าความคลาดเคลื่อนลดลง ข้อสรุปที่ถูกต้องสำหรับการศึกษานี้คือ ในการประเมินครั้งนี้ซึ่งทั้งข้อมูลดิบและข้อมูลที่ปรับแก้แล้วต่างมีอัตราส่วนการกระจายสูงกว่าค่าที่ทำให้ค่าความคลาดเคลื่อนต่ำสุด การคืนความแปรปรวนเพิ่มเติมจึงสัมพันธ์กับการเพิ่มขึ้นของค่า RMSE ข้อค้นพบนี้สอดคล้องกับข้อสังเกตของ Ehret et al. (2012) ที่ว่าการปรับแก้อคติเปลี่ยนคุณสมบัติทางสถิติของข้อมูลโดยไม่ได้ปรับปรุงกระบวนการทางกายภาพที่อยู่เบื้องหลัง"));

add(SUB("4.3 การปรับแก้อคติไม่สามารถสร้างความสอดคล้องเชิงเวลาที่ไม่มีในแบบจำลองเดิม"));
add(P("ผลจากหัวข้อ 3.4 แสดงว่าสัมประสิทธิ์สหสัมพันธ์ของค่าเบี่ยงรายเดือนไม่เปลี่ยนแปลง และของปริมาณฝนรายปีเพิ่มขึ้นเพียงเล็กน้อยจากระดับที่ใกล้ศูนย์ ผลดังกล่าวเป็นไปตามที่คาดหมายได้จากธรรมชาติของแบบจำลองภูมิอากาศโลกที่ดำเนินการแบบอิสระ ซึ่งมิได้ถูกออกแบบให้จำลองลำดับเหตุการณ์ฝนให้ตรงกับที่เกิดขึ้นจริงในแต่ละช่วงเวลา แต่มุ่งจำลองลักษณะทางสถิติของภูมิอากาศ (Gudmundsson et al., 2012)"));
add(P("ในเชิงคณิตศาสตร์ การปรับแก้แบบจับคู่ควอนไทล์เป็นการแปลงแบบเอกโทนต่อสถานี จึงไม่สามารถเปลี่ยนลำดับของค่าภายในอนุกรม และไม่สามารถสร้างสารสนเทศเชิงเวลาที่ไม่มีอยู่ในแบบจำลองเดิมได้ กล่าวโดยสรุป การปรับแก้อคติแปลงคุณสมบัติทางสถิติของข้อมูล แต่ไม่ได้สร้างสารสนเทศเชิงพลวัตที่ไม่ปรากฏในผลการจำลอง"));
add(P("ข้อเท็จจริงนี้ยังอธิบายการที่สัมประสิทธิ์สหสัมพันธ์ของวัฏจักรฤดูกาลลดลงเล็กน้อยเมื่อใช้การปรับแก้แบบรวมทุกเดือน และการที่ผลดีขึ้นชัดเจนเมื่อประมาณและตรึงฟังก์ชันการแปลงแยกตามเดือนปฏิทิน ดังผลการวิเคราะห์ความไวในหัวข้อ 3.6 ผลนี้สอดคล้องกับ Arif Rafhida et al. (2025) ซึ่งเปรียบเทียบการประมาณฟังก์ชันการแจกแจงแบบรายเดือนกับแบบรวมทุกเดือน ในการปรับแก้ข้อมูล CMIP6 บริเวณทะเลสาบโทบา และพบว่าประสิทธิผลของทั้งสองแนวทางขึ้นกับลักษณะของสถานี การจัดกลุ่มรายเดือนจึงเป็นแนวทางที่ควรพิจารณาในการศึกษาต่อไป อย่างไรก็ตาม การศึกษานี้คงใช้การรวมทุกเดือนเป็นวิธีหลัก เนื่องจากคำถามวิจัยหลักคือการถ่ายทอดข้ามช่วงเวลาของฟังก์ชันการแปลง มิใช่การเปรียบเทียบรูปแบบการตั้งค่า"));

add(SUB("4.4 นัยต่อการประเมินข้อมูลที่ผ่านการปรับแก้อคติ"));
add(P("ผลการศึกษาชี้ว่าการประเมินการปรับแก้อคติไม่ควรอาศัยแนวคิดสมรรถนะเพียงมิติเดียว การใช้ดัชนี RMSE หรือ NSE เพียงอย่างเดียวจะลงโทษการคืนความแปรปรวนที่สอดคล้องกับการตรวจวัดเมื่อสัมประสิทธิ์สหสัมพันธ์เชิงเวลาต่ำ และอาจนำไปสู่การเลือกวิธีการที่กดความแปรปรวนของข้อมูลจำลองไว้ต่ำกว่าความเป็นจริง ในทางกลับกัน การใช้ค่า PBIAS หรือค่าสถิติ Kolmogorov-Smirnov เพียงอย่างเดียวก็ไม่เพียงพอเช่นกัน เพราะไม่สะท้อนสมรรถนะเชิงเวลาแต่อย่างใด"));
add(P("การศึกษานี้จึงเสนอให้ประเมินการปรับแก้อคติในสามมิติที่แยกจากกัน ได้แก่ ความสมจริงเชิงการแจกแจง ซึ่งพิจารณาจากค่าสถิติ Kolmogorov-Smirnov ค่า Perkins skill score และความลำเอียงของควอนไทล์ ความคลาดเคลื่อนเชิงระบบ ซึ่งพิจารณาจากค่า PBIAS และสมรรถนะเชิงเวลา ซึ่งพิจารณาจากดัชนีที่อาศัยขนาดความคลาดเคลื่อนร่วมกับสัมประสิทธิ์สหสัมพันธ์ของค่าเบี่ยง แนวทางนี้สอดคล้องกับข้อเสนอของ Gupta et al. (2009) ที่ให้แยกพิจารณาองค์ประกอบด้านสหสัมพันธ์ ความแปรปรวน และความลำเอียงออกจากกัน แทนการสรุปด้วยดัชนีรวมเพียงค่าเดียว"));
add(P("ในเชิงการประยุกต์ใช้ ข้อมูลที่ผ่านการปรับแก้จากการศึกษานี้เหมาะสมกับงานที่อาศัยคุณสมบัติเชิงการแจกแจง เช่น การวิเคราะห์ความถี่ของเหตุการณ์ฝนหนัก การประเมินค่าฝนออกแบบ และการวิเคราะห์การเปลี่ยนแปลงของความเข้มฝน แต่ไม่เหมาะสมกับงานที่ต้องอาศัยความสอดคล้องของลำดับเหตุการณ์ เช่น การจำลองน้ำท่าแบบต่อเนื่อง"));

add(SUB("4.5 ข้อจำกัดของการศึกษา"));
add(P("ประการแรก การตรวจสอบใช้การแบ่งช่วงเวลาเพียงรูปแบบเดียวภายในบันทึกประวัติศาสตร์ ผลที่ได้จึงไม่สามารถยืนยันความคงที่ของความสัมพันธ์ของการปรับแก้ภายใต้สภาพภูมิอากาศในอนาคต ซึ่งเป็นสมมติฐานที่ Ehret et al. (2012) ตั้งข้อสงสัยไว้อย่างชัดเจน"));
add(P("ประการที่สอง การอนุมานเชิงสถิติอาศัยบล็อกรายปีเพียง 14 บล็อก ช่วงความเชื่อมั่นจากการสุ่มซ้ำจึงควรตีความเป็นการประเมินความไม่แน่นอนภายใต้บันทึกเวลาที่มีอยู่ มิใช่หลักฐานจากตัวอย่างเชิงเวลาอิสระที่ยาวเพียงพอสำหรับการอนุมานเชิงเส้นกำกับ"));
add(P("ประการที่สาม เนื่องจากการดึงข้อมูลด้วยจุดกริดที่ใกล้ที่สุดทำให้สถานีจำนวนหนึ่งใช้ค่าจากกริดเซลล์เดียวกันของแบบจำลอง คู่การประเมิน 60 คู่จึงควรตีความว่าเป็นจำนวนชุดการประเมิน มิใช่หน่วยเชิงพื้นที่ที่เป็นอิสระ 60 หน่วย สัดส่วนของคู่ที่ปรับปรุงขึ้นที่รายงานไว้จึงอธิบายความสม่ำเสมอของผลภายในการออกแบบการประเมิน มิใช่การทำซ้ำเชิงพื้นที่ที่เป็นอิสระต่อกัน ด้วยเหตุนี้ การศึกษาจึงไม่ใช้การทดสอบข้ามสถานีที่ตั้งอยู่บนสมมติฐานความเป็นอิสระ"));
add(P("ประการที่สี่ แม้สถานีทั้ง 12 แห่งจะผ่านเกณฑ์ควบคุมคุณภาพด้านความครบถ้วนและความเป็นเนื้อเดียว แต่ลักษณะของบันทึกมีความแตกต่างกันพอสมควร ดังแสดงในตารางที่ 1 โดยสถานีกลุ่มหนึ่งมีความเข้มฝนเฉลี่ยต่อวันฝนตกประมาณ 5 ถึง 6 มิลลิเมตรต่อวัน ควบคู่กับความถี่วันฝนตกและค่าสหสัมพันธ์ในตัวเองที่สูงกว่าสถานีอื่น ลักษณะดังกล่าวอาจสะท้อนวิธีปฏิบัติในการบันทึกหรือการเติมค่าที่แตกต่างกันระหว่างสถานี ซึ่งอยู่นอกเหนือขอบเขตที่การศึกษานี้ตรวจสอบได้จากข้อมูลที่มีอยู่ ผลการปรับแก้อคติที่รายงานรายสถานีในรูปที่ 5 จึงควรอ่านโดยคำนึงถึงความแตกต่างนี้ และการตรวจสอบที่มาของบันทึกในระดับหน่วยงานเจ้าของข้อมูลเป็นงานที่ควรดำเนินการต่อไป"));

/* ═══════════════════════════ CONCLUSIONS ═══════════════════════════ */
add(SEC("Conclusions"));
add(P("การศึกษานี้ประเมินวิธีควอนไทล์เดลตาแมปปิงด้วยกรอบการตรวจสอบความถูกต้องข้ามช่วงเวลาแบบอิสระ โดยประมาณความสัมพันธ์ของการปรับแก้จากข้อมูลช่วงปี ค.ศ. 1981-2000 แล้วตรึงค่าพารามิเตอร์และประเมินผลด้วยข้อมูลช่วงปี ค.ศ. 2001-2014 ที่ไม่เคยถูกใช้ในการปรับแก้ ในพื้นที่สถานีตรวจวัด 12 แห่ง ของจังหวัดประจวบคีรีขันธ์ ร่วมกับแบบจำลอง CMIP6 จำนวน 5 แบบจำลอง"));
add(P("ในช่วงตรวจสอบแบบอิสระ วิธีดังกล่าวปรับปรุงคุณสมบัติเชิงการแจกแจงในคู่การประเมินส่วนใหญ่ โดยค่าสถิติ Kolmogorov-Smirnov ลดลงจาก 0.201 เหลือ 0.105 ค่า Perkins skill score เพิ่มขึ้นจาก 0.776 เป็น 0.859 ความลำเอียงของควอนไทล์ที่ 99 ลดลงจากร้อยละ -29.2 เหลือร้อยละ -11.3 ความลำเอียงของดัชนี Rx1day ลดลงจากร้อยละ -19.9 เหลือร้อยละ -4.7 และค่า PBIAS ลดลงจากร้อยละ +9.45 เหลือร้อยละ -0.09 โดยปรับปรุงขึ้นในสัดส่วนร้อยละ 60 ถึง 85 ของคู่การประเมิน ในทางกลับกัน ค่า RMSE รายเดือนเพิ่มขึ้นจาก 116.2 เป็น 124.7 มิลลิเมตรต่อเดือน และค่า NSE ลดลงจาก -0.711 เป็น -0.974 โดยด้อยลงอย่างมีนัยสำคัญใน 32 จาก 60 คู่ สำหรับทั้งค่า RMSE และค่า NSE ภายหลังการควบคุมอัตราการค้นพบเท็จ การแยกส่วนค่าความคลาดเคลื่อนกำลังสองเฉลี่ยรายคู่ชี้ว่าพจน์การกระจายเป็นองค์ประกอบหลักของการด้อยลง โดยมีขนาดใหญ่ที่สุดใน 56 จาก 60 คู่ และมีค่าเฉลี่ยข้ามคู่เท่ากับ +2,891 เทียบกับพจน์ความลำเอียงที่ -237 ตารางมิลลิเมตรต่อเดือนกำลังสอง"));
add(P("สำหรับกลุ่มแบบจำลองเฉลี่ยแบบไม่ถ่วงน้ำหนัก พบว่ามีค่าความคลาดเคลื่อนต่ำกว่าแบบจำลองเดี่ยวทุกตัวในทุกสถานี ทั้งก่อนและหลังการปรับแก้ อย่างไรก็ตาม ค่า NSE ยังคงติดลบและสัมประสิทธิ์สหสัมพันธ์รายเดือนไม่ได้สูงกว่าแบบจำลองที่ดีที่สุด แสดงว่าข้อได้เปรียบของกลุ่มแบบจำลองเฉลี่ยเกิดจากการหักล้างกันของความคลาดเคลื่อนแบบสุ่ม มิใช่การเพิ่มขึ้นของความสามารถในการจำลอง จึงไม่ควรใช้ค่าเฉลี่ยเพียงค่าเดียวแทนความไม่แน่นอนระหว่างแบบจำลอง"));
add(P("โดยสรุป ผลการศึกษาให้หลักฐานว่าความสัมพันธ์ของการปรับแก้อคติมีความสามารถในการถ่ายทอดข้ามช่วงเวลาในระดับหนึ่งภายในบันทึกภูมิอากาศในอดีต สำหรับคุณสมบัติเชิงการแจกแจงบางประการ แต่ไม่ได้สร้างความสอดคล้องเชิงเวลาที่ไม่มีอยู่ในแบบจำลองเดิม ความสมจริงเชิงการแจกแจงและความแม่นยำของอนุกรมเวลาจึงเป็นคุณสมบัติคนละมิติกัน และไม่ควรใช้ดัชนี RMSE หรือ NSE เพียงลำพังเป็นเกณฑ์ตัดสินคุณภาพของการปรับแก้อคติ ทั้งนี้ ผลการตรวจสอบภายในบันทึกภูมิอากาศในอดีตยังไม่สามารถยืนยันได้ว่าความสัมพันธ์ที่ปรับเทียบไว้จะคงที่ภายใต้สภาพภูมิอากาศในอนาคต"));

